738	// ItemJourney 凭事项编号汇总它从建立到当前的处理经过：保留事项自身的
739	// 建立、修改、关闭记录，并加入它参与的各次交接（发起交接、逐轮退回、补充后
740	// 重新提交、确认接收或继续跟踪），无须先知道涉及哪些交接编号。
741	// 当前保存的处理结果是退回、却没有任何退回轮次记录时（旧数据缺失），仍在时间线
742	// 中呈现这次已发生的退回，处理人与处理时间各自使用该项当前保存的信息（缺失分别
743	// 标为未记录），并标明退回历史不完整、原因未记录；不编造轮次序号、原因、补充或
744	// 重新提交经过，也不拿交接发起时间补齐处理时间。待处理、确认接收、继续跟踪、
745	// 结果缺失或无法识别的记录不据残留的处理人与时间认定发生退回。
746	// 经过按实际发生时刻排序（带不同时区的时间按同一实际时刻比较）；同一时刻下
747	// 同一交接内保持发起、该轮退回、该轮重新提交、后续处理的先后，不同交接按
748	// 交接编号排列。同一次接收若已出现在事项历史里只展示一次：除操作人与实际
749	// 时刻相同外，还须接收说明明确记载的交接编号、交班、接班班次与接收方式都与
750	// 交接清单一致；任一记载不一致，或说明缺少明确记载（旧数据、没有对应交接
751	// 清单的接收历史）时，事项历史原样保留，不凭空补交接编号。只读查询，
752	// 不改变事项、交接进度或班次结束时记录。
753	func (svc *Service) ItemJourney(itemID string) (ItemJourney, error) {
754		itemID = clean(itemID)
755		d := &svc.store.data
756		it, _ := findItem(d, itemID)
757		if it == nil {
758			return ItemJourney{}, fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
759		}
760		j := ItemJourney{Item: *it}
761	
762		// 排序键：先按实际发生时刻（未记录时间的排最后），同一时刻下事项自身
763		// 事件在前，其后按交接编号分组，组内保持生成顺序（发起、逐轮退回、
764		// 该轮重新提交、后续处理）。
765		type keyedEvent struct {
766			ev    JourneyEvent
767			group string // "" 表示事项自身事件，否则为交接编号
768			ord   int    // 同一（时刻、分组）内的先后
769		}
770		var events []keyedEvent
771		seq := 0
772		add := func(ev JourneyEvent, group string) {
773			events = append(events, keyedEvent{ev: ev, group: group, ord: seq})
774			seq++
775		}
776	
777		// 接收记录的合并判定集中在 receivedMerge（见 received_merge.go）：遍历各次
778		// 交接清单时标记与某次接收同属一次的事项 received 事件，该事件随后只以信息
779		// 更全的交接事件展示。未标记的 received 事件（缺交接编号或交班班次的旧
780		// 说明、指向其他交接/班次/方式的说明、自由文字或残缺说明等）在下面原样保留。
781		merge := newReceivedMerge(it.Events)
782	
783		hs := append([]Handover(nil), d.Handovers...)
784		sort.Slice(hs, func(i, k int) bool { return hs[i].ID < hs[k].ID })
785		for k := range hs {
786			h := &hs[k]
787			e, _ := findEntry(h, itemID)
788			if e == nil {
789				continue
790			}
791			j.HasHandovers = true
792			j.Results = append(j.Results, EntryView{
793				HandoverID: h.ID,
794				FromShift:  h.FromShiftID,
795				ToShift:    h.ToShiftID,
796				Entry:      *e,
797			})
798	
799			// 发起交接：交接记录本身不记操作人，明确显示未记录，不以班次负责人代替。
800			add(JourneyEvent{
801				At: h.CreatedAt, TimeKnown: !h.CreatedAt.IsZero(),
802				Kind: "handover-init", HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
803			}, h.ID)
804			for _, r := range e.Rounds {
805				add(JourneyEvent{
806					At: r.ReturnedAt, TimeKnown: !r.ReturnedAt.IsZero(),
807					Kind: "return", Operator: r.ReturnOperator,
808					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
809					RoundSeq: r.Seq, Reason: r.Reason,
810				}, h.ID)
811				if r.ResubmittedAt != nil {
812					add(JourneyEvent{
813						At: *r.ResubmittedAt, TimeKnown: !r.ResubmittedAt.IsZero(),
814						Kind: "resubmit", Operator: r.SupplementOperator,
815						HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
816						RoundSeq: r.Seq, Supplement: r.Supplement,
817						SupplementOperator: r.SupplementOperator, SupplementAt: r.SupplementAt,
818					}, h.ID)
819				}
820			}
821			if e.Status == EntryReturned && len(e.Rounds) == 0 {
822				// 当前保存的结果是退回，却没有任何退回轮次记录（旧数据缺失）：
823				// 退回确实发生过，处理经过必须呈现这一事实，不能像没发生过退回一样
824				// 只列发起交接；但原因、轮次序号、补充与重新提交经过都没有可靠记录，
825				// 只能使用该项当前保存的处理人与处理时间，并标明退回历史不完整。
826				// 不编造第几次退回或退回原因，也不拿交接发起时间补齐处理时间。
827				ev := JourneyEvent{
828					Kind: "return-incomplete", Operator: e.Operator,
829					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
830					HistoryIncomplete: true,
831				}
832				if validProcessedAt(e.ProcessedAt) {
833					ev.At, ev.TimeKnown = *e.ProcessedAt, true
834				}
835				add(ev, h.ID)
836			}
837			if e.Status.Received() {
838				rcpt := receiptFromEntry(h, e)
839				ev := JourneyEvent{
840					Kind: rcpt.kind, Operator: e.Operator,
841					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
842					TrackingNote: e.TrackingNote,
843					// 继续跟踪当时指定的后续负责人取自交接记录快照，
844					// 之后修改事项负责人不改变这里的历史值。
845					FollowOwner: e.FollowOwner,
846				}
847				// 处理时间缺失或为旧数据零值时仍保留该处理事件，
848				// 时间标为未记录，排在有真实时间的事件之后；这种凭据 timeKnown
849				// 为 false，consider 不会合并任何事项事件（也不拿发起时间代替）。
850				if rcpt.timeKnown {
851					ev.At, ev.TimeKnown = rcpt.at, true
852				}
853				add(ev, h.ID)
854				// 标记与本次接收同属一次的事项 received 事件；合并依据全部在
855				// sameReceivedEvent 中：操作人与实际时刻相同，且说明完整记载
856				// 交接编号、交班、接班班次与接收方式并逐项一致。缺归属信息的
857				// 旧说明、残缺或自由文字说明一律不合并，原样作为独立接收历史。
858				merge.consider(rcpt)
859			}
860		}
861	
862		// 事项自身历史：建立、修改、关闭原样保留；未被合并掉的 received 事件
863		// （旧数据、指向其他归属的说明、自由文字等）也原样保留。
864		for i, iev := range it.Events {
865			if iev.Kind == "received" && merge.isUsed(i) {
866				continue
867			}
868			add(JourneyEvent{
869				At: iev.At, TimeKnown: !iev.At.IsZero(),
870				Kind: iev.Kind, Operator: iev.Operator, Detail: iev.Detail,
871			}, "")
872		}
873	
874		sort.SliceStable(events, func(i, k int) bool {
875			a, b := events[i], events[k]
876			if a.ev.TimeKnown != b.ev.TimeKnown {
877				return a.ev.TimeKnown
878			}
879			if a.ev.TimeKnown && !a.ev.At.Equal(b.ev.At) {
880				return a.ev.At.Before(b.ev.At)
881			}
882			if a.group != b.group {
883				return a.group < b.group
884			}
885			return a.ord < b.ord
886		})
887		for _, ke := range events {
888			j.Events = append(j.Events, ke.ev)
889		}
890		return j, nil
891	}
892	
